'use strict';
// Shared, round-robin planning budget: even blocked long-distance orders yield.
let unitPlans=new WeakMap(),unitPlanQueue=[];
function cancelUnitRoute(u){const p=unitPlans.get(u);if(p)p.cancelled=true;unitPlans.delete(u)}
function planUnitRoute(u,goal,longRange=false){const key=goal.x+','+goal.y;let p=unitPlans.get(u);if(!p||p.key!==key){cancelUnitRoute(u);p={u,key,task:residentRouteSearch(u,goal,longRange,(x,y)=>unitWalkable(u,x,y)),done:false};unitPlans.set(u,p);unitPlanQueue.push(p)}if(!p.done)return undefined;unitPlans.delete(u);return p.result}
function processUnitPlans(){for(let i=0;i<12&&unitPlanQueue.length;i++){const p=unitPlanQueue.shift();if(p.cancelled||unitPlans.get(p.u)!==p)continue;const result=p.task.next();if(result.done){p.done=true;p.result=result.value}else unitPlanQueue.push(p)}}
const qualitySimulation=simulationStep;
simulationStep=function(dt){processUnitPlans();qualitySimulation(dt)};
// Exploration only changes when the player crosses a tile boundary.
const qualityReveal=reveal;let lastRevealTile='';
reveal=function(){const key=Math.floor(state.p.x/T)+','+Math.floor(state.p.y/T);if(key===lastRevealTile)return;lastRevealTile=key;qualityReveal()};
function constructionHint(x,y,type=mode){const d=defs.find(d=>d[0]===type);if(!d)return '';if(!state.settled)return 'Najpierw załóż osadę przy rzece.';if(Math.hypot(x+.5-state.p.x/T,y+.5-state.p.y/T)>7)return 'Za daleko — podejdź na 7 pól.';if(type!=='sciezka'&&x===Math.floor(state.p.x/T)&&y===Math.floor(state.p.y/T))return 'To miejsce zajmuje Twój ludek.';const b=building(x,y),t=terrain(x,y),upgrade=b?.type==='sciezka'&&type!=='sciezka'||type==='brama'&&b?.type==='palisada'||type==='brama_swoi'&&['palisada','brama'].includes(b?.type)||['most','most_staly','palisada','brama','brama_swoi','pomost'].includes(type)&&b?.type==='wawoz'&&(type!=='pomost'||t==='water');if(t==='edge')return 'Koniec mapy.';if(foreignBuilding(x,y))return 'To budowla obcej osady.';if(['most','most_staly'].includes(type)&&['most','most_staly'].includes(b?.type))return 'Kliknij, aby obrócić most.';if(b&&!upgrade)return 'Pole zajęte — wybierz Rozbierz lub inne miejsce.';if(natural(x,y)&&!(['kamieniolom','zelazo','zloto'].includes(type)&&natural(x,y)==='rock'))return 'Usuń drzewo lub skałę toporkiem.';if(['most','most_staly'].includes(type)){if(!['water','ravine'].includes(t)&&b?.type!=='wawoz')return 'Most wymaga rzeki lub wąwozu.'}else if(t==='ravine'||t==='water'&&!['palisada','brama','brama_swoi','pomost'].includes(type))return 'Woda lub wąwóz — potrzebny most.';if(type==='port'&&![[1,0],[-1,0],[0,1],[0,-1]].some(([a,b])=>terrain(x+a,y+b)==='water'))return 'Port musi stać tuż przy wodzie.';if(type==='mlyn'&&!nearWater(x,y))return 'Młyn wymaga rzeki w pobliżu.';if(state.wood<d[3]||state.stone<d[4])return 'Brakuje: '+Math.max(0,d[3]-Math.floor(state.wood))+' drewna, '+Math.max(0,d[4]-Math.floor(state.stone))+' kamienia.';return 'Możesz budować · '+d[3]+' drewna · '+d[4]+' kamienia.'}
const qualityBuild=build;
build=function(x,y){const hint=constructionHint(x,y);const n=state.buildings.length;qualityBuild(x,y);if(state.buildings.length===n&&hint&&!hint.startsWith('Możesz')&&!hint.startsWith('Kliknij'))say(hint)};
function nearestRaidWarning(){const origin=state.settled||{x:state.p.x/T,y:state.p.y/T};let closest=null;for(const r of state.war.raids){if(r.camp||r.power<=0)continue;const p=routePosition(r),dx=p.x/T-origin.x,dy=p.y/T-origin.y,d=Math.hypot(dx,dy);if(!closest||d<closest.d)closest={d,dx,dy,r}}if(!closest)return '';const n=state.towns.find(t=>t.id===closest.r.townId)?.name||'Wróg';const direction=Math.abs(closest.dx)>Math.abs(closest.dy)?closest.dx>0?'wschodu →':'zachodu ←':closest.dy>0?'południa ↓':'północy ↑';return '⚠ '+n+' · od '+direction+' · '+Math.ceil(closest.d)+' pól od osady'}
const qualityUI=ui;
ui=function(){qualityUI();const warning=nearestRaidWarning();if(warning){$('raidAlert').style.display='block';$('raidAlert').textContent=warning}};
const qualityDrawActor=drawBattleActor;
drawBattleActor=function(u,color){qualityDrawActor(u,color);if((u.hp??8)>=8&&!u.healing){ctx.fillStyle='#28463a';ctx.fillRect(u.x-12,u.y-40,24,4);ctx.fillStyle='#b5db83';ctx.fillRect(u.x-12,u.y-40,24,4)}if(u.blocked){ctx.fillStyle='#ffd297';ctx.font='10px system-ui';ctx.fillText('Brak przejścia',u.x-32,u.y+20)}};
const qualityDraw=draw;
draw=function(){if(worldCursor)mouse=worldPoint(worldCursor);qualityDraw();if(!worldCursor||!mode||mode==='rozbiorka'||villageBuildDrag)return;const text=constructionHint(Math.floor(mouse.x/T),Math.floor(mouse.y/T));if(!text)return;ctx.save();ctx.fillStyle='#18382fee';ctx.fillRect(innerWidth/2-220,178,440,42);ctx.fillStyle=text.startsWith('Możesz')?'#d4edbb':'#ffd098';ctx.textAlign='center';ctx.font='14px system-ui';ctx.fillText(text,innerWidth/2,204);ctx.restore()};
function setPanelsCollapsed(collapsed){document.body.classList.toggle('compact-map',collapsed);$('panelsToggle').textContent=collapsed?'▣ Pokaż panele':'▣ Więcej mapy';$('panelsToggle').setAttribute('aria-pressed',String(collapsed));try{localStorage.setItem('zielona-dolina-compact',String(collapsed))}catch{}}
$('panelsToggle').onclick=()=>setPanelsCollapsed(!document.body.classList.contains('compact-map'));try{setPanelsCollapsed(localStorage.getItem('zielona-dolina-compact')==='true')}catch{}
